<section class="content-header"><h1><i class="fa fa-percent"></i> Reporte de ocupación</h1></section><section class="content"><div class="box box-primary no-print"><div class="box-body"><form method="get" class="form-inline"><label>Desde</label> <input type="date" class="form-control" name="desde" value="<?php echo html_escape($filtros['desde']); ?>"> <label>Hasta</label> <input type="date" class="form-control" name="hasta" value="<?php echo html_escape($filtros['hasta']); ?>"> <label>Comparar por</label> <select name="grupo" class="form-control"><?php foreach(array('ruta'=>'Ruta','horario'=>'Horario','vehiculo'=>'Vehículo','dia_semana'=>'Día semana','mes'=>'Mes') as $k=>$v): ?><option value="<?php echo $k; ?>" <?php echo $filtros['grupo']==$k?'selected':''; ?>><?php echo $v; ?></option><?php endforeach; ?></select> <select name="ruta_id" class="form-control"><option value="0">Todas las rutas</option><?php foreach($listas['rutas'] as $r): ?><option value="<?php echo $r['ruta_id']; ?>" <?php echo $filtros['ruta_id']==$r['ruta_id']?'selected':''; ?>><?php echo html_escape($r['ruta_nombre']); ?></option><?php endforeach; ?></select> <select name="vehiculo_id" class="form-control"><option value="0">Todos los vehículos</option><?php foreach($listas['vehiculos'] as $v): ?><option value="<?php echo $v['vehiculo_id']; ?>" <?php echo $filtros['vehiculo_id']==$v['vehiculo_id']?'selected':''; ?>><?php echo html_escape($v['vehiculo_placa'].' '.$v['vehiculo_marca']); ?></option><?php endforeach; ?></select> <button class="btn btn-primary"><i class="fa fa-search"></i> Generar</button></form></div></div>
<div class="box"><div class="box-header"><h3 class="box-title">Ocupación = Pasajes vendidos / Capacidad</h3><div class="pull-right no-print"><button onclick="window.print()" class="btn btn-default btn-sm"><i class="fa fa-print"></i> Imprimir</button> <a class="btn btn-success btn-sm" href="<?php echo site_url('reporte_ocupacion/csv').'?'.http_build_query($filtros); ?>"><i class="fa fa-file-excel-o"></i> Excel/CSV</a></div></div><div class="box-body"><div class="table-responsive"><table class="table table-bordered table-striped"><thead><tr><th>Comparación</th><th class="text-right">Viajes</th><th class="text-right">Capacidad</th><th class="text-right">Vendidos</th><th class="text-right">Reservados</th><th class="text-right">Disponibles</th><th class="text-right">Ocupación</th><th class="text-right">Venta neta</th></tr></thead><tbody><?php $tv=$tc=$tven=$tres=$tdis=$tn=0; foreach($filas as $r): $tv+=$r['viajes'];$tc+=$r['capacidad'];$tven+=$r['vendidos'];$tres+=$r['reservados'];$tdis+=$r['disponibles'];$tn+=$r['venta_neta']; ?><tr><td><b><?php echo html_escape($r['grupo']); ?></b></td><td class="text-right"><?php echo $r['viajes']; ?></td><td class="text-right"><?php echo $r['capacidad']; ?></td><td class="text-right"><?php echo $r['vendidos']; ?></td><td class="text-right"><?php echo $r['reservados']; ?></td><td class="text-right"><?php echo $r['disponibles']; ?></td><td class="text-right"><b><?php echo number_format($r['ocupacion'],1,',','.'); ?> %</b></td><td class="text-right">Bs <?php echo number_format($r['venta_neta'],2,',','.'); ?></td></tr><?php endforeach; ?></tbody><tfoot><tr class="info"><th>TOTAL / OCUPACIÓN PONDERADA</th><th class="text-right"><?php echo $tv; ?></th><th class="text-right"><?php echo $tc; ?></th><th class="text-right"><?php echo $tven; ?></th><th class="text-right"><?php echo $tres; ?></th><th class="text-right"><?php echo $tdis; ?></th><th class="text-right"><?php echo $tc>0?number_format($tven*100/$tc,1,',','.'):0; ?> %</th><th class="text-right">Bs <?php echo number_format($tn,2,',','.'); ?></th></tr></tfoot></table></div>
<h4 class="no-print">Gráfico de ocupación</h4><div class="no-print" style="max-width:1000px"><?php foreach($filas as $r): ?><div style="margin:7px 0"><div><b><?php echo html_escape($r['grupo']); ?></b> — <?php echo number_format($r['ocupacion'],1,',','.'); ?>%</div><div style="background:#eee;height:18px"><div style="background:#3c8dbc;height:18px;width:<?php echo min(100,max(0,$r['ocupacion'])); ?>%"></div></div></div><?php endforeach; ?></div>
</div></div></section><style media="print">.no-print,.main-header,.main-sidebar,.content-header,.main-footer{display:none!important}.content-wrapper{margin-left:0!important}.content{padding:0!important}</style>